#!/usr/bin/env node
// Retained author sources only; no workspace paths, credentials, installs or generated bytes are copied.
import { cpSync, existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const files = ['data', 'generators', 'generate.ts', 'prove-mesa.ts', 'shard.config.ts', 'tsconfig.json'];
/** @param {unknown} value @returns {Record<string, unknown>} */
function record(value) {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) throw new Error('Invalid author package metadata');
  return value;
}
/** @param {string} path @returns {Record<string, unknown>} */
function readRecord(path) { const value = /** @type {unknown} */ (JSON.parse(readFileSync(path, 'utf8'))); return record(value); }
/** Add the readable reference sources and scripts to an installed, otherwise empty author project. */
/** @param {string} project */
export function bootstrapAuthor(project) {
  const root = resolve(project), manifest = resolve(root, 'package.json');
  const input = readRecord(manifest);
  const dependencies = { ...record(input.dependencies ?? {}), ...record(input.devDependencies ?? {}) };
  for (const name of ['@wildshard/sdk', '@wildshard/format', '@wildshard/commons', 'three'])
    if (typeof dependencies[name] !== 'string') throw new Error(`Install ${name} before bootstrapping`);
  for (const name of files) if (existsSync(resolve(root, name))) throw new Error(`Refusing to replace existing author input: ${name}`);
  const template = readRecord(resolve(import.meta.dirname, 'package.json'));
  for (const name of files) cpSync(resolve(import.meta.dirname, name), resolve(root, name), { recursive: true });
  writeFileSync(manifest, `${JSON.stringify({ ...input, private: true, type: 'module', scripts: { ...record(input.scripts ?? {}), ...record(template.scripts) } }, null, 2)}\n`);
}
if (process.argv[1] !== undefined && resolve(process.argv[1]) === import.meta.filename) {
  const project = process.argv[2];
  if (project === undefined || process.argv.length !== 3) throw new Error('Usage: node bootstrap.mjs <installed-project>');
  bootstrapAuthor(project);
}
